public class Main {
    static class Node { int value; Node left, right; Node(int value) { this.value = value; } }
    static Node insert(Node root, int value) {
        if (root == null) return new Node(value);
        if (value < root.value) root.left = insert(root.left, value);
        else root.right = insert(root.right, value);
        return root;
    }
    static boolean contains(Node root, int value) {
        while (root != null) {
            if (root.value == value) return true;
            root = value < root.value ? root.left : root.right;
        }
        return false;
    }
    public static void main(String[] args) {
        Node root = null;
        for (int value : new int[]{8, 3, 10, 6, 4}) root = insert(root, value);
        System.out.println(contains(root, 4) + " " + root.left.left.value);
    }
}
